def ker(F, typ):
    L = F @ F.T / F.shape[1]
    d = np.maximum(0, np.diag(L)[:, None] + np.diag(L) - 2 * L)
    if typ == 0:
        return (1 + L) ** 2
    if typ == 1:
        return (1 + L) ** 3
    return (1 + L) ** 2 + np.exp(-typ * d)
